using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer.Tools;

[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the DI container provides HttpClient automatically
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'London' or 'New York'")] string city)
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"/v1/current.json?key=demo&q={Uri.EscapeDataString(city)}");

        if (response is null)
            return $"No weather data found for '{city}'.";

        return $"""
            Weather for {response.Location.Name}, {response.Location.Country}:
            Temperature: {response.Current.TempC}°C / {response.Current.TempF}°F
            Condition: {response.Current.Condition.Text}
            Humidity: {response.Current.Humidity}%
            Wind: {response.Current.WindKph} km/h
            """;
    }

    [McpServerTool, Description("Get weather forecast for a city for the next N days")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of forecast days (1-3)")] int days = 3)
    {
        days = Math.Clamp(days, 1, 3);

        var response = await _httpClient.GetAsync(
            $"/v1/forecast.json?key=demo&q={Uri.EscapeDataString(city)}&days={days}");

        if (!response.IsSuccessStatusCode)
            return $"Failed to get forecast for '{city}': {response.StatusCode}";

        var content = await response.Content.ReadAsStringAsync();
        return content;
    }
}

// Response models
public record WeatherResponse
{
    [JsonPropertyName("location")] public LocationInfo Location { get; init; } = default!;
    [JsonPropertyName("current")] public CurrentWeather Current { get; init; } = default!;
}

public record LocationInfo
{
    [JsonPropertyName("name")] public string Name { get; init; } = "";
    [JsonPropertyName("country")] public string Country { get; init; } = "";
}

public record CurrentWeather
{
    [JsonPropertyName("temp_c")] public double TempC { get; init; }
    [JsonPropertyName("temp_f")] public double TempF { get; init; }
    [JsonPropertyName("humidity")] public int Humidity { get; init; }
    [JsonPropertyName("wind_kph")] public double WindKph { get; init; }
    [JsonPropertyName("condition")] public ConditionInfo Condition { get; init; } = default!;
}

public record ConditionInfo
{
    [JsonPropertyName("text")] public string Text { get; init; } = "";
}

